const parseFullText = (fullText) => {
  if (!fullText) return null;
  const lines = fullText.split('\n').map(l => l.trim()).filter(Boolean);

  const archiveIdx = lines.findIndex(l => l === 'Archive');
  const tableIndices = [];
  lines.forEach((l, idx) => {
    if (l === 'TABLE') tableIndices.push(idx);
  });

  if (tableIndices.length < 2 || archiveIdx === -1) {
    return null;
  }

  const team1Name = lines[archiveIdx + 1];
  const team2Name = lines[archiveIdx + 2];

  const parseStatsBlock = (startIdx) => {
    let rank = '';
    let points = '';
    let form = '';
    let performance = [];
    let victories = '';
    let highestWin = '';
    let totalGoals = '';
    let avgGoals = '';

    for (let i = startIdx + 1; i < startIdx + 30 && i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith('#')) {
        rank = line;
      } else if (line === 'POINTS') {
        points = lines[i - 1];
      } else if (line === 'FORM') {
        form = lines[i - 1];
      } else if (line === 'PERFORMANCE') {
        let perfIdx = i + 1;
        while (perfIdx < lines.length && ['W', 'D', 'L'].includes(lines[perfIdx])) {
          performance.push(lines[perfIdx]);
          perfIdx++;
        }
      } else if (line === 'VICTORIES') {
        victories = lines[i - 1];
      } else if (line === 'Highest win') {
        highestWin = lines[i + 1];
      } else if (line === 'Total Goals') {
        totalGoals = lines[i + 1];
      } else if (line === 'Avg. goals/match') {
        avgGoals = lines[i + 1];
      } else if (line === 'TABLE' || line === 'Last meetings' || line === 'PLAYED') {
        break;
      }
    }

    return { rank, points, form, performance: performance.join(' '), victories, highestWin, totalGoals, avgGoals };
  };

  const team1Stats = parseStatsBlock(tableIndices[0]);
  const team2Stats = parseStatsBlock(tableIndices[1]);

  let played = '';
  let draws = '';
  const playedIdx = lines.findIndex(l => l === 'PLAYED');
  if (playedIdx !== -1) {
    played = lines[playedIdx - 1];
  }
  const drawIdx = lines.findIndex(l => l === 'DRAW');
  if (drawIdx !== -1) {
    draws = lines[drawIdx - 1];
  }

  let h2hSummary = null;
  const totalScoreIdx = lines.findIndex(l => l === 'TOTAL SCORE');
  if (totalScoreIdx !== -1 && totalScoreIdx + 6 <= lines.length) {
    h2hSummary = {
      t1Wins: lines[totalScoreIdx + 1],
      draws: lines[totalScoreIdx + 2],
      t2Wins: lines[totalScoreIdx + 3],
      t1Label: lines[totalScoreIdx + 4],
      drawLabel: lines[totalScoreIdx + 5],
      t2Label: lines[totalScoreIdx + 6]
    };
  }

  return {
    team1Name,
    team2Name,
    played,
    draws,
    team1Stats,
    team2Stats,
    h2hSummary
  };
};

const renderPerfBadges = (perfString) => {
  if (!perfString) return null;
  const items = perfString.split(' ').filter(Boolean);
  return (
    <div style={{ display: 'flex', gap: '4px', justifyContent: 'center', alignItems: 'center' }}>
      {items.map((letter, idx) => {
        let bg = '#64748b'; // Gray for D
        if (letter === 'W') bg = '#10b981'; // Emerald for W
        if (letter === 'L') bg = '#ef4444'; // Red for L
        return (
          <span
            key={idx}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              width: '1.25rem',
              height: '1.25rem',
              borderRadius: '50%',
              fontSize: '0.65rem',
              fontWeight: 'bold',
              color: '#ffffff',
              background: bg,
              boxShadow: '0 1px 2px rgba(0,0,0,0.2)'
            }}
          >
            {letter}
          </span>
        );
      })}
    </div>
  );
};

const renderMarkdownText = (text) => {
  if (!text) return null;

  const lines = text.split('\n');
  let insideList = false;
  const renderedElements = [];
  let listItems = [];

  const flushList = (key) => {
    if (listItems.length > 0) {
      renderedElements.push(
        <ul key={`list-${key}`} style={{ paddingLeft: '1.25rem', margin: '0.6rem 0', color: 'var(--text-secondary)', listStyleType: 'disc' }}>
          {listItems}
        </ul>
      );
      listItems = [];
      insideList = false;
    }
  };

  const parseInlineStyles = (lineText) => {
    let html = lineText
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    // Replace **bold** with <strong>
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong style="color: var(--text-primary); font-weight: 700;">$1</strong>');

    // Replace *italic* with <em>
    html = html.replace(/\*([^*]+)\*/g, '<em style="font-style: italic; opacity: 0.95;">$1</em>');

    // Handle inline code or highlights
    html = html.replace(/`([^`]+)`/g, '<code style="background: rgba(255,255,255,0.06); padding: 0.1rem 0.35rem; border-radius: 4px; font-family: monospace; font-size: 0.85em; color: var(--accent-primary); border: 1px solid rgba(255,255,255,0.03);">$1</code>');

    return html;
  };

  lines.forEach((line, index) => {
    const trimmedLine = line.trim();

    if (trimmedLine.startsWith('---')) {
      flushList(index);
      renderedElements.push(
        <hr key={index} style={{ border: 0, borderTop: '1px solid var(--border-color)', margin: '1.5rem 0' }} />
      );
    } else if (trimmedLine.startsWith('###')) {
      flushList(index);
      const content = trimmedLine.replace(/^###\s*/, '');
      renderedElements.push(
        <h4 key={index} style={{ margin: '1.5rem 0 0.6rem 0', color: 'var(--accent-primary)', fontSize: '0.96rem', fontWeight: 700, borderBottom: '1px solid rgba(255,255,255,0.05)', paddingBottom: '0.3rem', letterSpacing: '0.02em' }} dangerouslySetInnerHTML={{ __html: parseInlineStyles(content) }} />
      );
    } else if (trimmedLine.startsWith('##')) {
      flushList(index);
      const content = trimmedLine.replace(/^##\s*/, '');
      renderedElements.push(
        <h3 key={index} style={{ margin: '1.75rem 0 0.8rem 0', color: 'var(--text-primary)', fontSize: '1.15rem', fontWeight: 800 }} dangerouslySetInnerHTML={{ __html: parseInlineStyles(content) }} />
      );
    } else if (trimmedLine.startsWith('#')) {
      flushList(index);
      const content = trimmedLine.replace(/^#\s*/, '');
      renderedElements.push(
        <h2 key={index} style={{ margin: '2rem 0 1rem 0', color: 'var(--text-primary)', fontSize: '1.35rem', fontWeight: 800 }} dangerouslySetInnerHTML={{ __html: parseInlineStyles(content) }} />
      );
    } else if (trimmedLine.startsWith('- ') || trimmedLine.startsWith('* ')) {
      insideList = true;
      const content = trimmedLine.replace(/^[-*]\s*/, '');
      listItems.push(
        <li key={`li-${index}`} style={{ marginBottom: '0.4rem', lineHeight: '1.5', fontSize: '0.88rem' }} dangerouslySetInnerHTML={{ __html: parseInlineStyles(content) }} />
      );
    } else if (trimmedLine === '') {
      flushList(index);
      renderedElements.push(<div key={index} style={{ height: '0.4rem' }} />);
    } else {
      flushList(index);
      renderedElements.push(
        <p key={index} style={{ margin: '0.5rem 0', lineHeight: '1.6', fontSize: '0.88rem', color: 'var(--text-secondary)' }} dangerouslySetInnerHTML={{ __html: parseInlineStyles(trimmedLine) }} />
      );
    }
  });

  flushList(lines.length);
  return renderedElements;
};

const getQualifiedLiveMatches = (predictions, label) => {
  if (!predictions) return [];
  return predictions.filter(p => {
    if (p.scored_status !== 1) return false;

    if (label.includes('Halftime / Fulltime') || label.includes('HT/FT')) {
      const probs = p.predicted_probs || {};
      const htftKeys = ['htft11Prob', 'htft1XProb', 'htft12Prob', 'htftX1Prob', 'htftXXProb', 'htftX2Prob', 'htft21Prob', 'htft2XProb', 'htft22Prob'];
      const hasHTFT = htftKeys.some(k => (probs[k] || 0) > 0);
      return hasHTFT;
    }

    return true; // For other markets, all scored matches qualify
  });
};

const getMatchMarketDetails = (p, label) => {
  const probs = p.predicted_probs || {};
  const isScored = p.scored_status === 1;

  let h = 0, a = 0;
  let htH = 0, htA = 0;
  if (isScored && p.actual_score) {
    const parts = p.actual_score.split(':');
    h = Number(parts[0]);
    a = Number(parts[1]);
    const htParts = (p.actual_ht_score || '0:0').split(':');
    htH = Number(htParts[0]);
    htA = Number(htParts[1]);
  }

  const totalGoals = h + a;
  const htGoals = htH + htA;
  const shGoals = totalGoals - htGoals;

  let predicted = '-';
  let confidence = 0;
  let actual = '-';
  let status = 'PENDING';

  if (label.includes('Match Result (1X2)')) {
    predicted = p.predicted_result || '-';
    confidence = predicted === 'Home' ? probs.homeWinProb : predicted === 'Away' ? probs.awayWinProb : probs.drawProb;
    actual = !isScored ? '-' : h > a ? 'Home' : a > h ? 'Away' : 'Draw';
    status = !isScored ? 'PENDING' : predicted === actual ? 'WON' : 'LOST';
  } else if (label.includes('Over 1.5 Goals')) {
    predicted = (probs.over15Prob || 0) > 50 ? 'Over 1.5' : 'Under 1.5';
    confidence = (probs.over15Prob || 0) > 50 ? probs.over15Prob : 100 - (probs.over15Prob || 0);
    actual = !isScored ? '-' : totalGoals > 1.5 ? 'Over 1.5' : 'Under 1.5';
    status = !isScored ? 'PENDING' : (totalGoals > 1.5 ? 'WON' : 'LOST');
  } else if (label.includes('Under 1.5 Goals')) {
    predicted = (probs.over15Prob || 0) > 50 ? 'Over 1.5' : 'Under 1.5';
    confidence = (probs.over15Prob || 0) > 50 ? probs.over15Prob : 100 - (probs.over15Prob || 0);
    actual = !isScored ? '-' : totalGoals < 1.5 ? 'Under 1.5' : 'Over 1.5';
    status = !isScored ? 'PENDING' : (totalGoals < 1.5 ? 'WON' : 'LOST');
  } else if (label.includes('Over 2.5 Goals')) {
    predicted = (probs.over25Prob || 0) > 50 ? 'Over 2.5' : 'Under 2.5';
    confidence = (probs.over25Prob || 0) > 50 ? probs.over25Prob : 100 - (probs.over25Prob || 0);
    actual = !isScored ? '-' : totalGoals > 2.5 ? 'Over 2.5' : 'Under 2.5';
    status = !isScored ? 'PENDING' : (totalGoals > 2.5 ? 'WON' : 'LOST');
  } else if (label.includes('Under 2.5 Goals')) {
    predicted = (probs.over25Prob || 0) > 50 ? 'Over 2.5' : 'Under 2.5';
    confidence = (probs.over25Prob || 0) > 50 ? probs.over25Prob : 100 - (probs.over25Prob || 0);
    actual = !isScored ? '-' : totalGoals < 2.5 ? 'Under 2.5' : 'Over 2.5';
    status = !isScored ? 'PENDING' : (totalGoals < 2.5 ? 'WON' : 'LOST');
  } else if (label.includes('Over 3.5 Goals')) {
    predicted = (probs.over35Prob || 0) > 50 ? 'Over 3.5' : 'Under 3.5';
    confidence = (probs.over35Prob || 0) > 50 ? probs.over35Prob : 100 - (probs.over35Prob || 0);
    actual = !isScored ? '-' : totalGoals > 3.5 ? 'Over 3.5' : 'Under 3.5';
    status = !isScored ? 'PENDING' : (totalGoals > 3.5 ? 'WON' : 'LOST');
  } else if (label.includes('Under 3.5 Goals')) {
    predicted = (probs.over35Prob || 0) > 50 ? 'Over 3.5' : 'Under 3.5';
    confidence = (probs.over35Prob || 0) > 50 ? probs.over35Prob : 100 - (probs.over35Prob || 0);
    actual = !isScored ? '-' : totalGoals < 3.5 ? 'Under 3.5' : 'Over 3.5';
    status = !isScored ? 'PENDING' : (totalGoals < 3.5 ? 'WON' : 'LOST');
  } else if (label.includes('Over 4.5 Goals')) {
    predicted = (probs.over45Prob || 0) > 50 ? 'Over 4.5' : 'Under 4.5';
    confidence = (probs.over45Prob || 0) > 50 ? probs.over45Prob : 100 - (probs.over45Prob || 0);
    actual = !isScored ? '-' : totalGoals > 4.5 ? 'Over 4.5' : 'Under 4.5';
    status = !isScored ? 'PENDING' : (totalGoals > 4.5 ? 'WON' : 'LOST');
  } else if (label.includes('Under 4.5 Goals')) {
    predicted = (probs.over45Prob || 0) > 50 ? 'Over 4.5' : 'Under 4.5';
    confidence = (probs.over45Prob || 0) > 50 ? probs.over45Prob : 100 - (probs.over45Prob || 0);
    actual = !isScored ? '-' : totalGoals < 4.5 ? 'Under 4.5' : 'Over 4.5';
    status = !isScored ? 'PENDING' : (totalGoals < 4.5 ? 'WON' : 'LOST');
  } else if (label.includes('Over 5.5 Goals')) {
    predicted = (probs.over55Prob || 0) > 50 ? 'Over 5.5' : 'Under 5.5';
    confidence = (probs.over55Prob || 0) > 50 ? probs.over55Prob : 100 - (probs.over55Prob || 0);
    actual = !isScored ? '-' : totalGoals > 5.5 ? 'Over 5.5' : 'Under 5.5';
    status = !isScored ? 'PENDING' : (totalGoals > 5.5 ? 'WON' : 'LOST');
  } else if (label.includes('Under 5.5 Goals')) {
    predicted = (probs.over55Prob || 0) > 50 ? 'Over 5.5' : 'Under 5.5';
    confidence = (probs.over55Prob || 0) > 50 ? probs.over55Prob : 100 - (probs.over55Prob || 0);
    actual = !isScored ? '-' : totalGoals < 5.5 ? 'Under 5.5' : 'Over 5.5';
    status = !isScored ? 'PENDING' : (totalGoals < 5.5 ? 'WON' : 'LOST');
  } else if (label.includes('Both Teams Score (GG)')) {
    predicted = (probs.ggProb || 0) > 50 ? 'Yes' : 'No';
    confidence = (probs.ggProb || 0) > 50 ? probs.ggProb : 100 - (probs.ggProb || 0);
    actual = !isScored ? '-' : (h > 0 && a > 0) ? 'Yes' : 'No';
    status = !isScored ? 'PENDING' : ((h > 0 && a > 0) ? 'WON' : 'LOST');
  } else if (label.includes('HT over 2.5')) {
    predicted = (probs.htOver25Prob || 0) > 50 ? 'Over 2.5' : 'Under 2.5';
    confidence = (probs.htOver25Prob || 0) > 50 ? probs.htOver25Prob : 100 - (probs.htOver25Prob || 0);
    actual = !isScored ? '-' : htGoals > 2.5 ? 'Over 2.5' : 'Under 2.5';
    status = !isScored ? 'PENDING' : (htGoals > 2.5 ? 'WON' : 'LOST');
  } else if (label.includes('HT under 2.5')) {
    predicted = (probs.htOver25Prob || 0) > 50 ? 'Over 2.5' : 'Under 2.5';
    confidence = (probs.htOver25Prob || 0) > 50 ? probs.htOver25Prob : 100 - (probs.htOver25Prob || 0);
    actual = !isScored ? '-' : htGoals < 2.5 ? 'Under 2.5' : 'Over 2.5';
    status = !isScored ? 'PENDING' : (htGoals < 2.5 ? 'WON' : 'LOST');
  } else if (label.includes('HT over 3.5')) {
    predicted = (probs.htOver35Prob || 0) > 50 ? 'Over 3.5' : 'Under 3.5';
    confidence = (probs.htOver35Prob || 0) > 50 ? probs.htOver35Prob : 100 - (probs.htOver35Prob || 0);
    actual = !isScored ? '-' : htGoals > 3.5 ? 'Over 3.5' : 'Under 3.5';
    status = !isScored ? 'PENDING' : (htGoals > 3.5 ? 'WON' : 'LOST');
  } else if (label.includes('HT under 3.5')) {
    predicted = (probs.htOver35Prob || 0) > 50 ? 'Over 3.5' : 'Under 3.5';
    confidence = (probs.htOver35Prob || 0) > 50 ? probs.htOver35Prob : 100 - (probs.htOver35Prob || 0);
    actual = !isScored ? '-' : htGoals < 3.5 ? 'Under 3.5' : 'Over 3.5';
    status = !isScored ? 'PENDING' : (htGoals < 3.5 ? 'WON' : 'LOST');
  } else if (label.includes('Odd')) {
    predicted = (probs.oddProb || 0) > (probs.evenProb || 0) ? 'Odd' : 'Even';
    confidence = Math.max(probs.oddProb || 0, probs.evenProb || 0);
    actual = !isScored ? '-' : totalGoals % 2 === 1 ? 'Odd' : 'Even';
    status = !isScored ? 'PENDING' : (totalGoals % 2 === 1 ? 'WON' : 'LOST');
  } else if (label.includes('Even')) {
    predicted = (probs.oddProb || 0) > (probs.evenProb || 0) ? 'Odd' : 'Even';
    confidence = Math.max(probs.oddProb || 0, probs.evenProb || 0);
    actual = !isScored ? '-' : totalGoals % 2 === 0 ? 'Even' : 'Odd';
    status = !isScored ? 'PENDING' : (totalGoals % 2 === 0 ? 'WON' : 'LOST');
  } else if (label.includes('Highest Scoring Half (1st)')) {
    predicted = (probs.htScoring1stProb || 0) > Math.max(probs.htScoring2ndProb || 0, probs.htScoringEqualProb || 0) ? '1st Half' : '-';
    confidence = probs.htScoring1stProb || 0;
    actual = !isScored ? '-' : htGoals > shGoals ? '1st Half' : 'Other';
    status = !isScored ? 'PENDING' : (htGoals > shGoals ? 'WON' : 'LOST');
  } else if (label.includes('Highest Scoring Half (2nd)')) {
    predicted = (probs.htScoring2ndProb || 0) > Math.max(probs.htScoring1stProb || 0, probs.htScoringEqualProb || 0) ? '2nd Half' : '-';
    confidence = probs.htScoring2ndProb || 0;
    actual = !isScored ? '-' : shGoals > htGoals ? '2nd Half' : 'Other';
    status = !isScored ? 'PENDING' : (shGoals > htGoals ? 'WON' : 'LOST');
  } else if (label.includes('Highest Scoring Half (Equal)')) {
    predicted = (probs.htScoringEqualProb || 0) > Math.max(probs.htScoring1stProb || 0, probs.htScoring2ndProb || 0) ? 'Equal' : '-';
    confidence = probs.htScoringEqualProb || 0;
    actual = !isScored ? '-' : htGoals === shGoals ? 'Equal' : 'Other';
    status = !isScored ? 'PENDING' : (htGoals === shGoals ? 'WON' : 'LOST');
  } else if (label.includes('Halftime / Fulltime') || label.includes('HT/FT')) {
    const htftKeys = [
      { key: 'htft11Prob', label: '11' },
      { key: 'htft1XProb', label: '1X' },
      { key: 'htft12Prob', label: '12' },
      { key: 'htftX1Prob', label: 'X1' },
      { key: 'htftXXProb', label: 'XX' },
      { key: 'htftX2Prob', label: 'X2' },
      { key: 'htft21Prob', label: '21' },
      { key: 'htft2XProb', label: '2X' },
      { key: 'htft22Prob', label: '22' }
    ];
    const hasHTFT = htftKeys.some(item => (probs[item.key] || 0) > 0);
    let maxHTFTProb = 0;
    let predictedHTFT = 'N/A';
    if (hasHTFT) {
      htftKeys.forEach(item => {
        const pVal = probs[item.key] || 0;
        if (pVal > maxHTFTProb) {
          maxHTFTProb = pVal;
          predictedHTFT = item.label;
        }
      });
    }
    predicted = predictedHTFT;
    confidence = maxHTFTProb;
    const htOutcome = htH > htA ? '1' : (htH === htA ? 'X' : '2');
    const ftOutcome = h > a ? '1' : (h === a ? 'X' : '2');
    actual = !isScored ? '-' : `${htOutcome}${ftOutcome}`;
    status = !isScored ? 'PENDING' : (predicted === 'N/A' ? 'VOID' : (predicted === actual ? 'WON' : 'LOST'));
  }

  return { predicted, confidence, actual, status };
};

const getOppositeTip = (market) => {
  if (!market) return '';
  switch (market) {
    case 'Home Win': return 'Away Win or Draw (X2)';
    case 'Away Win': return 'Home Win or Draw (1X)';
    case 'Draw': return 'Home or Away Win (12)';
    case 'Both Teams to Score (GG)': return 'Both Teams to Score (No)';
    case 'Home Draw No Bet': return 'Away Draw No Bet';
    case 'Away Draw No Bet': return 'Home Draw No Bet';
    default:
      if (market.startsWith('Over ')) {
        return market.replace('Over ', 'Under ');
      }
      if (market.startsWith('Under ')) {
        return market.replace('Under ', 'Over ');
      }
      return 'Opposite of ' + market;
  }
};

// Inject pulse-red keyframe once
if (typeof document !== 'undefined' && !document.getElementById('pulse-red-style')) {
  const s = document.createElement('style');
  s.id = 'pulse-red-style';
  s.textContent = `@keyframes pulse-red { 0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(239,68,68,0.4)} 50%{opacity:0.85;box-shadow:0 0 0 4px rgba(239,68,68,0)} }`;
  document.head && document.head.appendChild(s);
}

function PremiumCountdown({ initialTime, theme }) {
  const [secondsLeft, setSecondsLeft] = useState(null);
  const lastServerSeconds = useRef(null);

  // Sync with server value: only update internal clock when the server
  // value differs by more than 5s (avoids flickering reset every poll cycle)
  useEffect(() => {
    if (!initialTime || !initialTime.includes(':')) {
      setSecondsLeft(null);
      lastServerSeconds.current = null;
      return;
    }
    const parts = initialTime.split(':');
    const minutes = parseInt(parts[0], 10) || 0;
    const seconds = parseInt(parts[1], 10) || 0;
    const incoming = minutes * 60 + seconds;

    // First time, or drift > 5 seconds from what we'd expect → hard sync
    const expected = lastServerSeconds.current !== null ? lastServerSeconds.current - 8 : null;
    if (expected === null || Math.abs(incoming - expected) > 5) {
      setSecondsLeft(incoming);
    }
    lastServerSeconds.current = incoming;
  }, [initialTime]);

  useEffect(() => {
    if (secondsLeft === null || secondsLeft <= 0) return;
    const timer = setInterval(() => {
      setSecondsLeft(prev => (prev !== null && prev > 0) ? prev - 1 : 0);
    }, 1000);
    return () => clearInterval(timer);
  }, [secondsLeft !== null && secondsLeft > 0 ? true : false]); // only re-attach when switching between 0/non-0

  if (secondsLeft === null) return null;

  const mins = Math.floor(secondsLeft / 60);
  const secs = secondsLeft % 60;
  const timeText = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  const isUrgent = secondsLeft <= 60;

  return (
    <span style={{
      fontSize: '0.75rem',
      background: isUrgent
        ? (theme === 'light' ? 'rgba(239, 68, 68, 0.15)' : 'rgba(248, 113, 113, 0.2)')
        : (theme === 'light' ? 'rgba(239, 68, 68, 0.08)' : 'rgba(248, 113, 113, 0.12)'),
      color: theme === 'light' ? '#dc2626' : '#f87171',
      borderRadius: '6px',
      padding: '0.2rem 0.5rem',
      fontWeight: 700,
      display: 'inline-flex',
      alignItems: 'center',
      gap: '0.25rem',
      border: isUrgent
        ? (theme === 'light' ? '1px solid rgba(239, 68, 68, 0.4)' : '1px solid rgba(248, 113, 113, 0.5)')
        : (theme === 'light' ? '1px solid rgba(239, 68, 68, 0.15)' : '1px solid rgba(248, 113, 113, 0.25)'),
      animation: isUrgent ? 'pulse-red 1s ease-in-out infinite' : 'none',
      transition: 'all 0.3s ease'
    }}>
      ⏱️ Clears in {timeText}
    </span>
  );
}

// Countdown driven purely from a Unix-ms kickoff timestamp — no scraper needed
// onExpired fires ONCE when the countdown hits zero
function KickoffCountdown({ kickoffMs, theme, onExpired }) {
  const [secondsLeft, setSecondsLeft] = useState(() => {
    if (!kickoffMs) return null;
    const diff = Math.max(0, Math.round((Number(kickoffMs) - Date.now()) / 1000));
    return diff <= 0 ? null : diff;
  });
  const firedRef = useRef(false);

  useEffect(() => {
    if (!kickoffMs) { setSecondsLeft(null); return; }
    // Recalculate from source every tick to avoid drift
    const tick = () => {
      const diff = Math.round((Number(kickoffMs) - Date.now()) / 1000);
      if (diff <= -300) {
        setSecondsLeft(null);
        // Fire onExpired exactly once
        if (!firedRef.current && onExpired) {
          firedRef.current = true;
          // Small delay so the UI clears before the DB delete refreshes data
          setTimeout(onExpired, 1500);
        }
      } else {
        setSecondsLeft(diff);
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [kickoffMs]);

  if (secondsLeft === null) return null;

  const hrs = Math.max(0, Math.floor(secondsLeft / 3600));
  const mins = Math.max(0, Math.floor((secondsLeft % 3600) / 60));
  const secs = Math.max(0, secondsLeft % 60);
  const isUrgent = secondsLeft > 0 && secondsLeft <= 120;
  const isPlaying = secondsLeft <= 0;

  const timeText = isPlaying
    ? `LIVE NOW`
    : hrs > 0
      ? `${hrs}h ${String(mins).padStart(2, '0')}m`
      : `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

  return (
    <span style={{
      fontSize: '0.75rem',
      background: isUrgent
        ? (theme === 'light' ? 'rgba(239,68,68,0.15)' : 'rgba(248,113,113,0.2)')
        : (theme === 'light' ? 'rgba(239,68,68,0.08)' : 'rgba(248,113,113,0.12)'),
      color: isUrgent
        ? (theme === 'light' ? '#dc2626' : '#f87171')
        : (theme === 'light' ? '#b45309' : '#fbbf24'),
      borderRadius: '6px',
      padding: '0.2rem 0.55rem',
      fontWeight: 700,
      display: 'inline-flex',
      alignItems: 'center',
      gap: '0.3rem',
      border: isUrgent
        ? (theme === 'light' ? '1px solid rgba(239,68,68,0.35)' : '1px solid rgba(248,113,113,0.45)')
        : (theme === 'light' ? '1px solid rgba(245,158,11,0.25)' : '1px solid rgba(251,191,36,0.25)'),
      animation: isUrgent ? 'pulse-red 1s ease-in-out infinite' : 'none',
      transition: 'all 0.3s ease',
      flexShrink: 0
    }}>
      ⏱️ Clears in {timeText}
    </span>
  );
}

