    const lower = seasonName.toLowerCase();
    const isBundesliga = lower.includes('bundesliga');
    const maxRounds = isBundesliga ? 30 : 38;
    const matchesPerRound = isBundesliga ? 8 : 10;
    return maxRounds * matchesPerRound;
