  const isTgKeySent = useCallback(async (key) => {
    // Fast L1: in-memory cache (covers same session)
    if (tgSentDbCache.current.has(key) || postedPredictionIdsRef.current.has(key) || postingKeysRef.current.has(key)) return true;
    // L2: persistent DB check (covers app restarts)
    try {
      const dbPath = getTgDbPath();
      const res = await window.api.queryDb(dbPath, 'SELECT 1 FROM telegram_sent_log WHERE msg_key = ? LIMIT 1', [key]);
      const rows = (res && res.success) ? (res.data || res.rows || []) : [];
      if (rows.length > 0) {
        tgSentDbCache.current.add(key); // promote to cache
        return true;
      }
    } catch (e) {}
    return false;
  }, [getTgDbPath]);

  const markTgKeySent = useCallback(async (key, msgType = 'unknown') => {
    if (!key) return;
    // Update in-memory immediately
    tgSentDbCache.current.add(key);
    markPredictionAsPosted(key);
    // Persist to DB
    try {
      const dbPath = getTgDbPath();
      await window.api.queryDb(dbPath,
        'INSERT OR IGNORE INTO telegram_sent_log (msg_key, msg_type) VALUES (?, ?)',
        [key, msgType]
      );
    } catch (e) { console.warn('[TG dedup] DB write failed:', e.message); }
  }, [getTgDbPath, markPredictionAsPosted]);

