        if (!res || !res.success || !res.report) {
          throw new Error('Failed to load data for ' + (platform === 'sportybet' ? 'SportyBet' : 'Bet9ja') + ' database.');
        }

        const calculated = getCalculatedStats(res.report, baseCapital, stakingMode, stakingValue);
