  // Auto-scroller for marked matches
  useEffect(() => {
    let intervalId = null;
    if (isAutoScrollingMarked && livePredictionsData && livePredictionsData.predictions) {
      const getMarked = () => {
        const unplayed = livePredictionsData.predictions.filter(p => p.scored_status === 0).map(p => {
          const probs = p.predicted_probs || {};
          let conf = p.confidence_score;
          if (!conf && probs) {
            const maxProb = Math.max(probs.homeWinProb || 0, probs.drawProb || 0, probs.awayWinProb || 0) / 100;
            conf = Math.round(40 + (maxProb - 0.33) * 85);
            conf = Math.max(50, Math.min(98, conf));
          }
          return { ...p, computedConfidence: conf || 50 };
        });

        return unplayed.filter(p => {
          const meetsConfidence = p.computedConfidence >= liveConfidenceFilter;
          const isMarked = predictionNotes[p.id]?.marked;
          if (!isMarked) return false;
          if (!upcomingSearchQuery) return meetsConfidence;
          const query = upcomingSearchQuery.toLowerCase();
          const homeMatch = p.home_team?.toLowerCase().includes(query);
          const awayMatch = p.away_team?.toLowerCase().includes(query);

          const probs = p.predicted_probs || {};
          const over25Val = probs.over25Prob || 0;
          const under25Val = 100 - over25Val;
          const over15Val = probs.over15Prob || 0;
          let goalsTip = 'No Clear Bet';
          if (over25Val > 50) goalsTip = 'Over 2.5';
          else if (under25Val > 50) goalsTip = 'Under 2.5';
          else if (over15Val > 70) goalsTip = 'Over 1.5';

          const oeTip = (probs.oddProb || 0) > (probs.evenProb || 0) ? 'Odd' : 'Even';

          const maxHalfProb = Math.max(probs.htScoring1stProb || 0, probs.htScoring2ndProb || 0, probs.htScoringEqualProb || 0);
          let halfTip = 'Equal';
          if (maxHalfProb === probs.htScoring1stProb) halfTip = '1st Half';
          else if (maxHalfProb === probs.htScoring2ndProb) halfTip = '2nd Half';

          const bttsTip = (probs.ggProb || 0) > 50 ? 'Yes' : 'No';

          const resultMatch = p.predicted_result?.toLowerCase().includes(query);
          const goalsMatch = goalsTip.toLowerCase().includes(query);
          const oeMatch = oeTip.toLowerCase().includes(query);
          const halfMatch = halfTip.toLowerCase().includes(query);
          const bttsMatch = bttsTip.toLowerCase() === query;
          const bttsLabelMatch = query.includes('btts') && (query.includes('yes') ? bttsTip === 'Yes' : query.includes('no') ? bttsTip === 'No' : true);

          return meetsConfidence && (
            homeMatch ||
            awayMatch ||
            resultMatch ||
            goalsMatch ||
            oeMatch ||
            halfMatch ||
            bttsMatch ||
            bttsLabelMatch
          );
        });
      };

      const markedList = getMarked();

      if (markedList.length > 0) {
        let currentIndex = 0;

        const focusOnIndex = (index) => {
          const target = markedList[index];
          if (target) {
            setActiveAutoScrollId(target.id);
            const el = document.querySelector(`[data-match-id="${target.id}"]`);
            if (el) {
              el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
          }
        };

        focusOnIndex(0);

        intervalId = setInterval(() => {
          const freshMarked = getMarked();
          if (freshMarked.length === 0) {
            setIsAutoScrollingMarked(false);
            setActiveAutoScrollId(null);
            return;
          }
          currentIndex = (currentIndex + 1) % freshMarked.length;
          const target = freshMarked[currentIndex];
          if (target) {
            setActiveAutoScrollId(target.id);
            const el = document.querySelector(`[data-match-id="${target.id}"]`);
            if (el) {
              el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
          }
        }, autoScrollInterval * 1000);
      } else {
        setIsAutoScrollingMarked(false);
        setActiveAutoScrollId(null);
      }
    } else {
      setActiveAutoScrollId(null);
    }

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [isAutoScrollingMarked, autoScrollInterval, livePredictionsData, predictionNotes, liveConfidenceFilter, upcomingSearchQuery]);

  // Background checker for marked kickoff times
  useEffect(() => {
    let checkInterval;
    if (livePredictionsData && livePredictionsData.predictions) {
      const checkAlarms = () => {
        const now = new Date();
        livePredictionsData.predictions.forEach(p => {
          const isMarked = predictionNotes[p.id]?.marked;
          const isHistoryMarked = (livePredictionsData.aiPicksHistory || []).some(h =>
            h.status === 'pending' &&
            bookmarkedIds.includes(h.id) &&
            h.home_team === p.home_team &&
            h.away_team === p.away_team &&
            h.season_name === p.season_name
          );
          const isUnplayed = p.scored_status === 0;
          const isDismissed = dismissedAlarms.includes(p.id);

          if ((isMarked || isHistoryMarked) && isUnplayed && !isDismissed) {
            if (!p.match_time) return;
            const [mHours, mMinutes] = p.match_time.split(':').map(Number);
            const matchTime = new Date(now);
            matchTime.setHours(mHours, mMinutes, 0, 0);

            // Adjust for wrapping around midnight
            let diffMs = matchTime.getTime() - now.getTime();
            if (diffMs < -12 * 60 * 60 * 1000) {
              matchTime.setDate(matchTime.getDate() + 1);
              diffMs = matchTime.getTime() - now.getTime();
            } else if (diffMs > 12 * 60 * 60 * 1000) {
              matchTime.setDate(matchTime.getDate() - 1);
              diffMs = matchTime.getTime() - now.getTime();
            }

            const diffMins = diffMs / (60 * 1000);

            // Sound alarm if kickoff is approaching and still in the future
            if (diffMins > 0 && diffMins <= alarmMinutesBefore) {
              setActiveAlarmPrediction(p);
            }
          }
        });
      };

      checkAlarms();
      checkInterval = setInterval(() => {
        if (typeof document !== 'undefined' && document.hidden) return;
        checkAlarms();
      }, 15000);
    }
    return () => {
      if (checkInterval) clearInterval(checkInterval);
    };
  }, [livePredictionsData, predictionNotes, dismissedAlarms, alarmMinutesBefore, bookmarkedIds]);

