  /**
   * Checks if any automatic cleaners (Smart Clear / OS Temp) are due to run,
   * based on the frequency settings saved in config. Called on bot launch
   * and on a background 1-hour interval.
   */
  const checkAndRunAutoCleaners = async (currentConfig) => {
    const cfg = currentConfig || config;
    const now = Date.now();

    // --- Smart Clear ---
    const scFreq = cfg?.maintenance?.smartClear?.frequency || 'manually';
    const scLastRun = cfg?.maintenance?.smartClear?.lastAutoRun ? new Date(cfg.maintenance.smartClear.lastAutoRun).getTime() : 0;
    let scDue = false;
    if (scFreq === 'every-launch') scDue = true;
    else if (scFreq === 'daily') scDue = (now - scLastRun) >= 24 * 60 * 60 * 1000;
    else if (scFreq === 'weekly') scDue = (now - scLastRun) >= 7 * 24 * 60 * 60 * 1000;

    if (scDue) {
      console.log('[Auto-Cleaner] Smart Clear is due — running automatically...');
      const res = await window.api.smartClearData();
      if (res.success) {
        // Record last run time in config
        const updatedConfig = {
          ...cfg,
          maintenance: {
            ...cfg.maintenance,
            smartClear: {
              ...cfg.maintenance?.smartClear,
              lastAutoRun: new Date().toISOString()
            }
          }
        };
        setConfig(updatedConfig);
        await window.api.writeConfig(updatedConfig);
      }
    }

    // --- OS Temp Clear ---
    const otFreq = cfg?.maintenance?.osTempClear?.frequency || 'manually';
    const otLastRun = cfg?.maintenance?.osTempClear?.lastAutoRun ? new Date(cfg.maintenance.osTempClear.lastAutoRun).getTime() : 0;
    let otDue = false;
    if (otFreq === 'every-launch') otDue = true;
    else if (otFreq === 'daily') otDue = (now - otLastRun) >= 24 * 60 * 60 * 1000;
    else if (otFreq === 'weekly') otDue = (now - otLastRun) >= 7 * 24 * 60 * 60 * 1000;

    if (otDue) {
      console.log('[Auto-Cleaner] OS Temp clear is due — running automatically...');
      if (!window.api?.clearOsTempProfiles) {
        console.warn('[Auto-Cleaner] clearOsTempProfiles API not exposed yet. Please restart the dashboard app.');
      } else {
        const res = await window.api.clearOsTempProfiles();
        if (res.success) {
          const updatedConfig = {
            ...cfg,
            maintenance: {
              ...cfg.maintenance,
              osTempClear: {
                ...cfg.maintenance?.osTempClear,
                lastAutoRun: new Date().toISOString()
              }
            }
          };
          setConfig(updatedConfig);
          await window.api.writeConfig(updatedConfig);
          if (res.cleaned > 0) {
            console.log(`[Auto-Cleaner] OS Temp: removed ${res.cleaned} orphaned profile(s).`);
          }
        }
      }
    }


  };

  const handleStart = async (script = selectedScript, overrideOptions = null) => {
    const activeLaunchMode = overrideOptions?.launchMode || launchMode
    const activeProfileType = overrideOptions?.profileType || profileType
    if (activeLaunchMode === 'single' && activeProfileType === 'existing' && !selectedProfileId && !overrideOptions?.specificProfile) {
      alert('Please select an existing profile to launch.')
      return
    }

    const options = {
      instanceCount,
      profileType: profileType === 'existing' ? 'permanent' : profileType,
      family: selectedFamily,
      launchMode,
      randomCount,
      device: manualDevice,
      browser: manualBrowser,
      headless: headlessMode,
      concurrencyLimit: parseInt(concurrencyLimit) || 3,
      specificProfile: profileType === 'existing' ? selectedProfileId : null,
      ...overrideOptions
    }

    // Run any due auto-cleaners BEFORE starting the bot
    await checkAndRunAutoCleaners(config);

    const res = await window.api.startBot(script, options)
    if (res.success) {
      if (res.warnings && res.warnings.length > 0) {
        alert(res.warnings.join('\n'))
      }
      // Refresh status immediately
      window.api.getBotStatus().then(data => {
        if (typeof data === 'object') {
          setStatus(data.status)
          setRunningInstances(data.instances || [])
        } else {
          setStatus(data)
        }
      })
    }
  }

