  // ─── Live Season: fetch predictions and scrape/predict live season ──────────
  const fetchLivePredictions = async (overrideLimit, force = false) => {
    if (isFetchingLivePredictionsRef.current && !force) return;
    // Route to the correct DB: sportybet uses its own DB, bet9ja uses the predictor DB
    let db;
    if (livePlatform === 'sportybet') {
      db = selectedSportyDb || (dbFiles.length > 0 ? (dbFiles.find(f => f === 'sportybet_archive.db') || dbFiles[0]) : null);
    } else {
      db = selectedPredictorDb || selectedDb || (dbFiles.length > 0 ? (dbFiles.find(f => f === 'virtual_football_archive.db') || dbFiles.find(f => f === 'sportybet_archive.db') || dbFiles[0]) : null);
    }
    if (!db || !botSettings.outputDir) {
      setLivePredictionsError('No database selected or output directory not set.');
      return;
    }
    setIsLivePredictionsLoading(true);
    setLivePredictionsError('');
    isFetchingLivePredictionsRef.current = true;
    try {
      const dbPath = joinPath(botSettings.outputDir, db);
      const limitToUse = overrideLimit !== undefined ? Math.min(overrideLimit, 500) : Math.min(historyMaxLimitRef.current || 300, 500);
      console.log(`[Renderer fetchLivePredictions] Invoking getLivePredictions: dbPath=${dbPath}, platform=${livePlatform}, limit=${limitToUse}`);
      const res = await window.api.getLivePredictions({ dbPath, provider: livePlatform, limit: limitToUse });
      console.log(`[Renderer fetchLivePredictions] Got response: success=${res?.success}, preds=${res?.predictions?.length || 0}`);
      if (res.success) {
        res.platform = livePlatform;
        setLivePredictionsData(res);
        const preds = res.predictions || [];
        const hasUpcomingOrRecent = preds.some(p => {
          if (p.scored_status === 0) return true;
          const kickoffMs = getMatchKickoffMs(p);
          return kickoffMs && (Date.now() - kickoffMs < 10 * 60 * 1000);
        });
        const latestId = preds.length > 0 ? Math.max(...preds.map(p => p.id || 0)) : 0;
        const prevLatestId = lastSeenPredictionIdRef.current[livePlatform] || 0;
        if (hasUpcomingOrRecent || (latestId > 0 && latestId !== prevLatestId)) {
          lastPredictionReceivedTimeRef.current[livePlatform] = Date.now();
          lastSeenPredictionIdRef.current[livePlatform] = latestId;
        }
      } else {
        setLivePredictionsError(res.error || 'Failed to fetch live predictions.');
      }
    } catch (err) {
      setLivePredictionsError('Error: ' + err.message);
    } finally {
      setIsLivePredictionsLoading(false);
      isFetchingLivePredictionsRef.current = false;
    }
  };



  const handleViewMarketHistory = async (isSilent = false, retryCount = 0) => {
    const silent = isSilent === true;
    if (!silent) {
      setShowMarketHistory(true);
      setIsMarketHistoryLoading(true);
      setIsScrapingHistory(true);
    }
    try {
      let db;
      if (livePlatform === 'sportybet') {
        db = selectedSportyDb || (dbFiles.length > 0 ? (dbFiles.find(f => f === 'sportybet_archive.db') || dbFiles[0]) : null);
      } else {
        db = selectedPredictorDb || selectedDb || (dbFiles.length > 0 ? (dbFiles.find(f => f === 'virtual_football_archive.db') || dbFiles[0]) : null);
      }
      if (!db || !botSettings.outputDir) {
        if (!silent) alert('Database not found.');
        return;
      }
      const dbPath = joinPath(botSettings.outputDir, db);

      const fetchHistoryFromDb = async (targetDbPath) => {
        const checkTableRes = await window.api.queryDb(targetDbPath, "SELECT name FROM sqlite_master WHERE type='table' AND name='historical_market_predictions'", []);
        const tableExists = checkTableRes && checkTableRes.success && checkTableRes.data && checkTableRes.data.length > 0;

        let hasLeagueId = false;
        try {
          const pragmaRes = await window.api.queryDb(targetDbPath, "PRAGMA table_info('live_predictions')", []);
          hasLeagueId = pragmaRes && pragmaRes.success && Array.isArray(pragmaRes.data) && pragmaRes.data.some(r => r.name === 'league_id');
        } catch (pragmaErr) {
          hasLeagueId = false;
        }

        const leagueIdSelect = hasLeagueId ? 'lp.league_id' : 'null as league_id';

        let historyQuery = '';
        if (tableExists) {
          historyQuery = `
            SELECT
              lp.id, lp.season_name, lp.round_number, lp.match_time,
              lp.home_team, lp.away_team, lp.predicted_result,
              COALESCE(hp.predicted_probs, lp.predicted_probs) AS predicted_probs,
              COALESCE(lp.actual_score, hp.actual_score) AS actual_score,
              COALESCE(lp.actual_ht_score, hp.actual_ht_score) AS actual_ht_score,
              lp.scored_status,
              COALESCE(hp.kickoff_timestamp, lp.kickoff_timestamp) AS kickoff_timestamp,
              lp.bookmaker_odds,
              ${leagueIdSelect}
            FROM live_predictions lp
            LEFT JOIN historical_market_predictions hp
              ON hp.season_name   = lp.season_name
             AND hp.home_team     = lp.home_team
             AND hp.away_team     = lp.away_team
             AND hp.round_number  = lp.round_number

            UNION

            SELECT
              hp.id, hp.season_name, hp.round_number, hp.match_time,
              hp.home_team, hp.away_team, null as predicted_result,
              hp.predicted_probs,
              hp.actual_score, hp.actual_ht_score, 0 as scored_status,
              hp.kickoff_timestamp,
              null as bookmaker_odds,
              null as league_id
            FROM historical_market_predictions hp
            WHERE NOT EXISTS (
              SELECT 1 FROM live_predictions lp
              WHERE lp.season_name = hp.season_name
                AND lp.home_team   = hp.home_team
                AND lp.away_team   = hp.away_team
                AND lp.round_number = hp.round_number
            )
            ORDER BY kickoff_timestamp DESC
            LIMIT 2000
          `;
        } else {
          historyQuery = `
            SELECT
              lp.id, lp.season_name, lp.round_number, lp.match_time,
              lp.home_team, lp.away_team, lp.predicted_result,
              lp.predicted_probs,
              lp.actual_score, lp.actual_ht_score, lp.scored_status,
              lp.kickoff_timestamp,
              lp.bookmaker_odds,
              ${leagueIdSelect}
            FROM live_predictions lp
            ORDER BY lp.kickoff_timestamp DESC
            LIMIT 2000
          `;
        }
        return await window.api.queryDb(targetDbPath, historyQuery, []);
      };

      let res = await fetchHistoryFromDb(dbPath);

      // Auto-fallback: If primary DB has no predictions, search other archive databases (e.g. sportybet_archive.db)
      if (res && res.success && (!res.data || res.data.length === 0)) {
        const altFiles = (dbFiles || []).filter(f => f && f.endsWith('.db') && f !== db);
        for (const altFile of altFiles) {
          const altPath = joinPath(botSettings.outputDir, altFile);
          try {
            const altRes = await fetchHistoryFromDb(altPath);
            if (altRes && altRes.success && altRes.data && altRes.data.length > 0) {
              res = altRes;
              break;
            }
          } catch (altErr) {}
        }
      }

      if (res && res.success) {
        setMarketHistoryData(res.data || []);
      } else if (res && res.error && res.error.includes('ECONNECT')) {
        // Connection error - retry after delay
        if (retryCount < 2) {
          console.warn('[Market History] Connection error, retrying in 2s...');
          setTimeout(() => handleViewMarketHistory(isSilent, retryCount + 1), 2000);
          return;
        }
        if (!silent) alert('Database connection error. Please check your database connection and try again.');
      } else {
        setMarketHistoryData([]);
        if (!silent && res?.error && !res.error.includes('no such table')) {
          alert('Failed to fetch history: ' + res.error);
        }
      }
    } catch (err) {
      // Handle connection errors
      if (err.message && err.message.includes('ECONNECT')) {
        if (retryCount < 2) {
          console.warn('[Market History] Connection error, retrying in 2s...');
          setTimeout(() => handleViewMarketHistory(isSilent, retryCount + 1), 2000);
          return;
        }
        if (!silent) alert('Database connection error. Please check your database connection and try again.');
      } else {
        if (!silent) alert('Error fetching market history: ' + err.message);
      }
    } finally {
      if (!silent) {
        setIsMarketHistoryLoading(false);
        setIsScrapingHistory(false);
      }
      setLastMarketSync(Date.now());
    }
  };

