  const handleSaveKeywords = async () => {
    const platform = getPlatform(selectedScript)
    if (!platform) return
    const res = await window.api.writeKeywords({ content: keywords, platform })
    if (res.success) alert(`${platform.toUpperCase()} Keywords updated!`)
  }

  const handleImportProxies = async () => {
    const lines = bulkProxyText.split('\n').map(l => l.trim()).filter(l => l)
    const newProxies = lines.map(line => {
      // host:port:user:pass or host:port
      const parts = line.split(':')
      return {
        host: parts[0],
        port: parts[1],
        username: parts[2] || '',
        password: parts[3] || '',
        protocol: 'http',
        assignedProfiles: []
      }
    })

    const updated = [...proxies, ...newProxies]
    const res = await window.api.saveProxies(updated)
    if (res.success) {
      setProxies(updated)
      setBulkProxyText('')
      alert(`Imported ${newProxies.length} proxies!`)
    }
  }

  const handleAssignProxy = async () => {
    if (!assigningProxy || selectedProfilesToAssign.length === 0) return

    const profilesToAssign = selectedProfilesToAssign.map(id => ({ id, family: assignTargetFamily }))
    const res = await window.api.assignProxy({ proxy: assigningProxy, profiles: profilesToAssign })

    if (res.success) {
      if (res.warnings && res.warnings.length > 0) {
        const msg = res.warnings.map(w => `⚠️ Profile "${w.profile}" already had proxy [${w.oldProxy}] assigned. It has been updated to the new proxy.`).join('\n')
        alert(`Proxy assigned successfully!\n\nWarnings:\n${msg}`)
      } else {
        alert('Proxy assigned successfully!')
      }
      setAssigningProxy(null)
      setSelectedProfilesToAssign([])
      window.api.getProxies().then(setProxies)
    } else {
      alert('Error: ' + res.error)
    }
  }

  const handleDeleteProxy = async (proxy) => {
    if (confirm(`Are you sure you want to delete proxy ${proxy.host}:${proxy.port}?`)) {
      const updated = proxies.filter(p => !(p.host === proxy.host && p.port === proxy.port))
      const res = await window.api.saveProxies(updated)
      if (res.success) setProxies(updated)
    }
  }

  const handleSelectProxiesFile = async () => {
    const res = await window.api.selectProxiesFile()
    if (res.success) {
      setBulkProxyText(res.content)
    }
  }

  const handleDeleteAllProfiles = async () => {
    if (confirm('⚠️ WARNING: This will permanently delete ALL bot profiles and ALL families. This action cannot be undone. Are you absolutely sure?')) {
      const res = await window.api.deleteAllProfiles()
      if (res.success) {
        window.api.getFamilies().then(setFamilies)
      }
    }
  }

  const handleClearData = async () => {
    if ((status || 'stopped').startsWith('running')) {
      showCleanerToast('error', '⚠️ Bots Still Running', 'Please stop all bots before clearing browser data.');
      return;
    }
    if (!confirm('Are you sure you want to clear all browser data? This will wipe the primary browser profile AND remove any orphaned OS temp profiles (bot-temp-*) from Windows/Linux temp directories.')) return;

    const res = await window.api.clearBrowserData();
    if (res.success) {
      const osTempMsg = res.osTempCleaned > 0 ? ` Also removed ${res.osTempCleaned} OS temp profile(s).` : '';
      showCleanerToast('success', '✅ Browser Data Cleared', `Browser profile wiped successfully.${osTempMsg}`);
    } else {
      showCleanerToast('error', '❌ Browser Clear Failed', res.error || 'Unknown error');
    }
  }

  const handleClearOsTemp = async () => {
    if (!window.api?.clearOsTempProfiles) {
      showCleanerToast('error', '⚠️ Restart Required', 'Please restart the dashboard app (npm run dashboard) to reload the background Electron process.');
      return;
    }
    if ((status || 'stopped').startsWith('running')) {
      showCleanerToast('error', '⚠️ Bots Still Running', 'Please stop all bots before clearing OS temporary profiles.');
      return;
    }
    if (!confirm('This will scan the OS temp folder (Windows: %LOCALAPPDATA%\\Temp, Linux: /tmp) and delete all orphaned bot-temp-* browser profile directories left behind by previous bot sessions. Active/running bots will be skipped safely. Continue?')) return;

    setIsOsTempClearing(true);
    showCleanerToast('info', '🧹 OS Temp Profiles', 'Scanning and removing bot-temp-* folders...');
    try {
      const res = await window.api.clearOsTempProfiles();
      if (res.success) {
        if (res.cleaned === 0 && res.skipped === 0) {
          showCleanerToast('success', '✅ OS Temp Already Clean', 'No bot-temp-* profiles found in the OS temp folder.');
        } else {
          const skipMsg = res.skipped > 0 ? ` (${res.skipped} still locked/active, skipped)` : '';
          showCleanerToast('success', '✅ OS Temp Profiles Cleared', `Removed ${res.cleaned} orphaned profile(s).${skipMsg}`);
        }
      } else {
        showCleanerToast('error', '❌ OS Temp Clear Failed', res.error || 'Unknown error');
      }
    } catch (err) {
      showCleanerToast('error', '❌ OS Temp Clear Error', err.message);
    } finally {
      setIsOsTempClearing(false);
    }
  }



  const handleSmartClear = async () => {
    if ((status || 'stopped').startsWith('running')) {
      showCleanerToast('error', '⚠️ Bots Still Running', 'Please stop all bots before starting a Smart Clear.');
      return;
    }
    if (!confirm('This will clear cache and temporal storage while fully preserving all website cookies and logged-in sessions. Continue?')) return;

    setActiveTab('dashboard');
    setIsSmartClearing(true);
    showCleanerToast('info', '⚡ Smart Clear', 'Clearing cache and temporal storage… preserving all sessions.');
    try {
      const res = await window.api.smartClearData();
      if (res.success) {
        showCleanerToast('success', '✅ Smart Clear Complete', 'Cache wiped. All cookies and login sessions fully preserved.');
      } else {
        showCleanerToast('error', '❌ Smart Clear Failed', res.error || 'Unknown error');
      }
    } catch (err) {
      showCleanerToast('error', '❌ Smart Clear Error', err.message);
    } finally {
      setIsSmartClearing(false);
    }
  }

  const formatBytes = (bytes, decimals = 2) => {
    if (bytes === undefined || bytes === null || isNaN(bytes) || bytes < 0) return '0 Bytes'
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const dm = decimals < 0 ? 0 : decimals
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
    const i = Math.min(sizes.length - 1, Math.floor(Math.log(bytes) / Math.log(k)))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i]
  }

  const freeRamPercent = stats ? (stats.system.freeMem / stats.system.totalMem) * 100 : 100;
  const freeDiskPercent = stats ? (stats.system.freeDisk / stats.system.totalDisk) * 100 : 100;

  const ramStatus = !stats ? 'normal' :
    (freeRamPercent < 15) ? 'critical' :
      (freeRamPercent < 30) ? 'warning' : 'normal';

  const diskStatus = !stats ? 'normal' :
    (freeDiskPercent < 10) ? 'critical' :
      (freeDiskPercent < 20) ? 'warning' : 'normal';

  const systemAlerts = [];
  if (stats) {
    if (ramStatus === 'critical' && !ignoredAlerts.includes('ram')) {
      systemAlerts.push({
        id: 'ram',
        type: 'critical',
        message: `🔴 CRITICAL: System Free RAM is extremely low (${freeRamPercent.toFixed(1)}% free)!`,
        actionText: 'Running active bots may crash your system. Stop some running instances or optimize memory immediately.',
        btnText: 'Stop Active Bots',
        action: () => handleStop()
      });
    } else if (ramStatus === 'warning' && !ignoredAlerts.includes('ram')) {
      systemAlerts.push({
        id: 'ram',
        type: 'warning',
        message: `⚠️ WARNING: High system RAM usage detected (only ${freeRamPercent.toFixed(1)}% free).`,
        actionText: 'Running concurrent instances may experience performance lags. Run Smart Cleaner to optimize active memory caches.',
        btnText: 'Run Smart Cleaner',
        action: () => handleSmartClear()
      });
    }

    if (diskStatus === 'critical' && !ignoredAlerts.includes('disk')) {
      systemAlerts.push({
        id: 'disk',
        type: 'critical',
        message: `🔴 CRITICAL: Available space on C: drive is dangerously low (${freeDiskPercent.toFixed(1)}% free)!`,
        actionText: 'Run the Smart Cleaner now to delete physical browser caches and free up space immediately.',
        btnText: 'Run Smart Cleaner',
        action: () => handleSmartClear()
      });
    } else if (diskStatus === 'warning' && !ignoredAlerts.includes('disk')) {
      systemAlerts.push({
        id: 'disk',
        type: 'warning',
        message: `⚠️ WARNING: Available space on C: drive is running low (${freeDiskPercent.toFixed(1)}% free).`,
        actionText: 'Wiping persistent browser cache folders will free up significant disk space safely.',
        btnText: 'Run Smart Cleaner',
        action: () => handleSmartClear()
      });
    }
  }

