                                  background: historyStatsMode === 'filtered' ? 'var(--accent-primary)' : 'transparent',
                                  color: historyStatsMode === 'filtered' ? '#fff' : 'var(--text-secondary)',
                                  border: 'none',
                                  borderRadius: '6px',
                                  padding: '0.25rem 0.6rem',
                                  fontSize: '0.75rem',
                                  fontWeight: 700,
