                                        {livePlatform === 'sportybet' ? 'Week' : 'Round'} <span style={{ fontSize: '0.8rem', opacity: 0.7 }}>{historySortField === 'round' ? (historySortOrder === 'desc' ? '▼' : '▲') : '↕'}</span>
